// Dữ liệu 20 bài HSK3 — từ vựng, nghĩa theo bảng từ của Giáo trình chuẩn HSK3 (bản tiếng Việt), chú thích ngữ pháp theo mục lục.
// Hội thoại, câu ví dụ và truyện do app tự viết (không chép từ sách).
const LESSONS=[{"n":1,"zh":"周末你有什么打算？","vi":"Cuối tuần bạn định làm gì?","topic":"Kế hoạch cuối tuần","words":[["啊","a","a","nhé, nhỉ, à (trợ từ cuối câu, làm câu nhẹ nhàng hơn)"],["搬","bān","ban","dọn, chuyển (đồ, nhà)"],["北方","běifāng","bắc phương","phương Bắc, miền Bắc"],["打算","dǎsuàn","đả toán","dự định; kế hoạch"],["带","dài","đới","mang theo, đem theo"],["地图","dìtú","địa đồ","bản đồ"],["复习","fùxí","phục tập","ôn tập, ôn bài"],["跟","gēn","cân","cùng, với"],["面包","miànbāo","diện bao","bánh mì"],["南","nán","nam","phía nam, miền Nam"],["一直","yìzhí","nhất trực","suốt, luôn luôn; thẳng"],["游戏","yóuxì","du hí","trò chơi, game"],["着急","zháojí","trước cấp","sốt ruột, lo lắng"],["周末","zhōumò","chu mạt","cuối tuần"],["作业","zuòyè","tác nghiệp","bài tập (về nhà)"]],"grammar":[{"t":"Bổ ngữ kết quả 好","f":"V + 好","e":"Đặt 好 sau động từ để nói việc đã làm xong và làm cho đâu ra đấy (sẵn sàng, ổn thỏa). Phủ định dùng 没 + V + 好, không dùng 不. Người Việt hay quên 好 và chỉ nói 我准备了, nghe như “có chuẩn bị” chứ chưa chắc đã xong.","ex":[["作业 你 写 好 了 吗？","Bài tập con làm xong chưa?"],["地图 我 已经 带 好 了。","Bản đồ mình đã mang theo đầy đủ rồi."],["饭 还 没 做 好， 你们 再 等 一下。","Cơm vẫn chưa nấu xong, mọi người đợi thêm chút nhé."]]},{"t":"Phủ định tuyệt đối 一……也/都 + 不/没……","f":"一 + lượng từ (+ N) + 也/都 + 不/没 + V/A","e":"Nghĩa là “không… một chút nào / không một… nào”. Cụm 一 + lượng từ + danh từ phải đưa lên TRƯỚC 也/都, không đặt sau động từ như tiếng Việt. Việc đã qua dùng 没, thói quen hoặc tính chất dùng 不.","ex":[["这 个 周末 我 一点儿 也 不 忙。","Cuối tuần này mình chẳng bận chút nào."],["我 今天 一 个 面包 都 没 吃。","Hôm nay mình chưa ăn cái bánh mì nào."],["他 一 次 也 没 去过 北方。","Anh ấy chưa đi miền Bắc lần nào."]]},{"t":"Liên từ 那 (vậy thì)","f":"(Câu của người kia), 那 + S + V","e":"那 đứng đầu câu, nối tiếp điều người khác vừa nói hoặc tình huống vừa nêu, nghĩa là “vậy thì, thế thì”. Nó khác 那 “kia” (đại từ chỉ định). Không đặt 那 sau chủ ngữ.","ex":[["你 不 想 玩儿 游戏？ 那 我们 去 看 电影 吧。","Bạn không muốn chơi game à? Vậy mình đi xem phim nhé."],["明天 下雨？ 那 我们 就 不 去 了。","Mai mưa à? Vậy mình không đi nữa."],["你 不 舒服？ 那 早点儿 休息 吧。","Bạn không khỏe à? Vậy nghỉ sớm đi."]]}],"dialog":[["A","这个周末你有什么打算？","Cuối tuần này bạn có dự định gì không?"],["B","我要帮朋友搬家，他要搬到学校南边。","Mình phải giúp bạn chuyển nhà, cậu ấy sắp dọn đến phía nam trường."],["A","你一直这么忙，作业写好了吗？","Bạn bận suốt như vậy, bài tập làm xong chưa?"],["B","还没写好呢，可是我一点儿也不着急。","Vẫn chưa xong, nhưng mình chẳng sốt ruột chút nào."],["A","那星期天你跟我一起复习吧。","Vậy Chủ nhật bạn ôn bài cùng mình nhé."],["B","好啊！我带面包去。","Được đấy! Mình mang bánh mì đến."]],"radicals":["土","十"],"write":["南","包"],"hz":{"note":"指事字 (chữ chỉ sự): 一 二 三 上 下 本 末","old":["游客","外地","北门"],"prov":["不到长城非好汉","Bất đáo Trường Thành phi hảo hán"]}},
{"n":2,"zh":"他什么时候回来？","vi":"Khi nào anh ấy quay về?","topic":"Ở văn phòng","words":[["把","bǎ","bả","cái, cây (lượng từ cho vật có tay cầm: dù, ghế…)"],["办公室","bàngōngshì","biện công thất","văn phòng"],["脚","jiǎo","cước","bàn chân"],["经理","jīnglǐ","kinh lý","giám đốc, quản lý"],["辆","liàng","lượng","chiếc (lượng từ cho xe)"],["楼","lóu","lâu","tòa nhà; tầng, lầu"],["拿","ná","nã","cầm, lấy"],["难","nán","nan","khó"],["胖","pàng","bàn","béo, mập"],["其实","qíshí","kỳ thực","thật ra"],["容易","róngyì","dung dị","dễ, dễ dàng"],["伞","sǎn","tản","cái ô, cây dù"],["瘦","shòu","sấu","gầy, ốm"],["树","shù","thụ","cây"],["疼","téng","đông","đau, nhức"],["腿","tuǐ","thối","chân, cẳng chân"],["秘书","mìshū","bí thư","thư ký","*"],["太太","tàitai","thái thái","bà; vợ","*"]],"grammar":[{"t":"Bổ ngữ xu hướng đơn 来 / 去","f":"V + 来/去；V + nơi chốn + 来/去","e":"Sau động từ thêm 来 nếu hành động hướng về phía người nói, thêm 去 nếu rời xa người nói. Nếu có từ chỉ nơi chốn thì đặt nó GIỮA động từ và 来/去 (上楼去), người Việt hay đặt sai thành 上去楼.","ex":[["经理 上 楼 去 了。","Giám đốc lên lầu rồi."],["外面 下雨 了， 你 拿 一 把 伞 去 吧。","Ngoài trời mưa rồi, bạn cầm một cây dù đi nhé."],["外面 冷， 快 进来 吧！","Ngoài này lạnh, mau vào đi!"]]},{"t":"Hai hành động xảy ra liên tiếp","f":"V1 + 了 + (O1) + 就 + V2","e":"Hành động thứ hai xảy ra ngay sau khi xong hành động thứ nhất: “… xong là …”. 了 đặt ngay sau V1, 就 đứng trước V2. Người Việt hay bỏ 了 hoặc đặt 就 trước chủ ngữ.","ex":[["我 下 了 课 就 去 你 家。","Tan học xong là mình tới nhà bạn."],["他 吃 了 午饭 就 回 办公室 了。","Ăn trưa xong là anh ấy về văn phòng ngay."],["明天 我 起 了 床 就 去 跑步。","Mai dậy xong là mình đi chạy bộ."]]},{"t":"Câu hỏi tu từ 能……吗？","f":"能 + V + 吗？ / 能 + 不 + V/A + 吗？","e":"Câu hỏi không cần trả lời, dùng để khẳng định ý ngược lại: 能…吗 = “làm sao mà … được” (không thể); 能不…吗 = “sao mà không … được” (chắc chắn có). Thường có lý do đứng phía trước.","ex":[["你 每天 吃 这么 多 蛋糕， 能 不 胖 吗？","Ngày nào cũng ăn nhiều bánh kem thế, sao mà không béo được?"],["这么 难 的 题， 他 能 做 对 吗？","Bài khó thế này, cậu ấy làm đúng sao được?"],["他 的 腿 还 疼 呢， 能 去 踢 足球 吗？","Chân cậu ấy còn đau, sao mà đi đá bóng được?"]]}],"dialog":[["A","李秘书，王经理在办公室吗？","Thư ký Lý, giám đốc Vương có ở văn phòng không?"],["B","不在，他刚才下楼去了。","Không ạ, ông ấy vừa xuống lầu rồi."],["A","他什么时候回来？","Khi nào ông ấy quay lại?"],["B","他吃了午饭就回来。","Ông ấy ăn trưa xong là về ngay ạ."],["A","外面下雨了，他带伞了吗？","Ngoài trời mưa rồi, ông ấy có mang dù không?"],["B","没带。其实他的伞就在办公室里。","Không mang ạ. Thật ra dù của ông ấy để ngay trong văn phòng."]],"radicals":["车","禾"],"write":["伞","胖"],"hz":{"old":["办公楼","外出","午觉"],"prov":["饭后百步走，活到九十九","Đi bộ trăm bước sau bữa ăn, sống đến chín mươi chín"]}},
{"n":3,"zh":"桌子上放着很多饮料。","vi":"Trên bàn để rất nhiều đồ uống.","topic":"Đồ uống và mua sắm","words":[["衬衫","chènshān","sấn sam","áo sơ mi"],["放","fàng","phóng","đặt, để"],["还是","háishi","hoàn thị","hay là (trong câu hỏi)"],["花","huā","hoa","hoa"],["或者","huòzhě","hoặc giả","hoặc (trong câu kể)"],["记得","jìde","ký đắc","nhớ, còn nhớ"],["裤子","kùzi","khố tử","cái quần"],["绿","lǜ","lục","xanh lá cây"],["爬山","pá shān","ba sơn","leo núi"],["舒服","shūfu","thư phục","dễ chịu, thoải mái"],["甜","tián","điềm","ngọt"],["条","tiáo","điều","chiếc, con (lượng từ cho quần, váy, cá, đường…)"],["小心","xiǎoxīn","tiểu tâm","cẩn thận"],["新鲜","xīnxiān","tân tiên","tươi, tươi mới"],["饮料","yǐnliào","ẩm liệu","đồ uống"],["元","yuán","nguyên","đồng, tệ (đơn vị tiền)"],["只","zhǐ","chỉ","chỉ"]],"grammar":[{"t":"Phân biệt 还是 và 或者","f":"A 还是 B？ (câu hỏi) / A 或者 B (câu kể)","e":"Cả hai đều dịch là “hay, hoặc”. 还是 dùng trong câu hỏi lựa chọn, bắt người nghe chọn một; 或者 dùng trong câu kể, nghĩa là chọn cái nào cũng được. Người Việt hay dùng 或者 trong câu hỏi, đó là lỗi.","ex":[["你 喝 茶 还是 喝 咖啡？","Bạn uống trà hay uống cà phê?"],["周末 我 去 爬山 或者 去 游泳。","Cuối tuần mình đi leo núi hoặc đi bơi."],["我 不 知道 他 今天 来 还是 明天 来。","Mình không biết anh ấy đến hôm nay hay ngày mai."]]},{"t":"Diễn tả sự tồn tại","f":"Nơi chốn + V着 + số lượng + N","e":"Dùng để tả ở chỗ nào đó có cái gì, đang ở trạng thái nào. Nơi chốn đứng đầu câu và không cần thêm 在; sau động từ phải có 着. Người Việt hay nói 在桌子上放着… hoặc quên 着.","ex":[["桌子 上 放 着 两 杯 饮料。","Trên bàn để hai cốc đồ uống."],["门口 站 着 一 个 人。","Ở cửa có một người đang đứng."],["床 上 放 着 一 条 新 裤子。","Trên giường để một chiếc quần mới."]]},{"t":"会 chỉ khả năng (sẽ)","f":"(不)会 + V (+ 的)","e":"会 ở đây diễn tả phán đoán một việc có khả năng xảy ra: “sẽ, có thể sẽ”. Phủ định là 不会; cuối câu hay thêm 的 để khẳng định chắc chắn. Khác với 会 “biết (làm gì)” đã học.","ex":[["明天 会 下雨 吗？","Mai có mưa không nhỉ?"],["你 穿 这么 少， 会 生病 的。","Bạn mặc ít thế, sẽ ốm đấy."],["别 着急， 他 不 会 忘 的。","Đừng sốt ruột, anh ấy sẽ không quên đâu."]]}],"dialog":[["A","桌子上放着很多饮料，你喝茶还是喝咖啡？","Trên bàn có nhiều đồ uống lắm, bạn uống trà hay cà phê?"],["B","我不喝咖啡，晚上喝咖啡会睡不着。","Mình không uống cà phê, tối uống cà phê sẽ mất ngủ."],["A","那喝牛奶吧，很新鲜。","Vậy uống sữa nhé, sữa tươi lắm."],["B","好啊。对了，你还记得明天去爬山吗？","Được đấy. À này, bạn còn nhớ mai đi leo núi không?"],["A","记得。我们七点或者七点半走都可以。","Nhớ chứ. Mình đi lúc bảy giờ hoặc bảy rưỡi đều được."]],"radicals":["衤","米"],"write":["甜","元"],"hz":{"old":["鲜奶","冷饮","上面"],"prov":["茶好客常来","Trà ngon khách thường đến"]}},
{"n":4,"zh":"她总是笑着跟客人说话。","vi":"Cô ấy luôn mỉm cười khi nói chuyện với khách.","topic":"Tính cách và con người","words":[["比赛","bǐsài","tỷ tái","trận đấu, cuộc thi"],["超市","chāoshì","siêu thị","siêu thị"],["聪明","cōngming","thông minh","thông minh"],["蛋糕","dàngāo","đản cao","bánh ngọt, bánh kem"],["饿","è","ngạ","đói"],["分","fēn","phân","xu (1/100 tệ); điểm; chia"],["回答","huídá","hồi đáp","trả lời"],["角","jiǎo","giác","hào (1/10 tệ); góc"],["客人","kèrén","khách nhân","khách"],["年级","niánjí","niên cấp","lớp, khối lớp (năm học)"],["年轻","niánqīng","niên khinh","trẻ, trẻ tuổi"],["努力","nǔlì","nỗ lực","cố gắng, chăm chỉ"],["热情","rèqíng","nhiệt tình","nhiệt tình, niềm nở"],["认真","rènzhēn","nhận chân","nghiêm túc, chăm chú"],["又","yòu","hựu","vừa…; lại"],["站","zhàn","trạm","đứng"],["照片","zhàopiàn","chiếu phiến","bức ảnh"],["总是","zǒngshì","tổng thị","luôn luôn, lúc nào cũng"]],"grammar":[{"t":"Cấu trúc 又……又……","f":"又 + A1 + 又 + A2","e":"Nghĩa là “vừa… vừa…”, nối hai tính chất hoặc hai trạng thái cùng có. Hai vế thường cùng tốt hoặc cùng xấu. Sau 又 không thêm 很 / 非常.","ex":[["这 个 蛋糕 又 好看 又 好吃。","Cái bánh này vừa đẹp vừa ngon."],["她 又 年轻 又 聪明。","Cô ấy vừa trẻ vừa thông minh."],["我 现在 又 冷 又 饿。","Bây giờ mình vừa lạnh vừa đói."]]},{"t":"Hành động đi kèm: V1着 + V2","f":"S + V1着 (+ O1) + V2 (+ O2)","e":"V1着 diễn tả cách thức hoặc tư thế khi làm việc chính V2: “… mà …”, “trong lúc …”. Động từ chính là V2, nên V1着 luôn đứng trước. Người Việt hay đảo lại theo tiếng Việt (说话笑着) là sai.","ex":[["他 站 着 回答 老师 的 问题。","Bạn ấy đứng trả lời câu hỏi của thầy."],["我们 走 着 去 超市 吧。","Mình đi bộ tới siêu thị nhé."],["妈妈 笑 着 说：“ 你 真 聪明！”","Mẹ cười nói: “Con thông minh thật!”"]]},{"t":"Cách nói số tiền","f":"số + 元(块) + số + 角(毛) + số + 分","e":"Văn viết dùng 元 / 角 / 分, khẩu ngữ dùng 块 / 毛 / 分 (1 元 = 10 角 = 100 分). Đơn vị cuối cùng thường được lược bỏ: 三块五 = 3,5 tệ. Số 2 đứng trước đơn vị đọc là 两: 两块, 两毛.","ex":[["这 个 蛋糕 二十八 元 五 角。","Cái bánh này hai mươi tám tệ năm hào."],["一 个 面包 三 块 五。","Một cái bánh mì ba tệ rưỡi."],["一共 十 块 零 五 分。","Tổng cộng mười tệ không hào năm xu."]]}],"dialog":[["A","你看，这是我们班的照片。","Cậu xem, đây là ảnh lớp mình."],["B","站着笑的那个女孩是谁？又年轻又漂亮。","Cô bạn đứng cười kia là ai thế? Vừa trẻ vừa xinh."],["A","她是我们班长，又聪明又努力。","Cậu ấy là lớp trưởng lớp mình, vừa thông minh vừa chăm chỉ."],["B","她学习一定很认真吧？","Chắc cậu ấy học hành nghiêm túc lắm nhỉ?"],["A","对，老师问问题，她总是第一个回答。","Đúng, thầy hỏi gì cậu ấy cũng là người trả lời đầu tiên."],["B","真不错！","Giỏi thật!"]],"radicals":["力","立"],"write":["角"],"hz":{"old":["女孩","做客","鲜花"],"prov":["五十步笑百步","Lươn ngắn lại chê chạch dài"]}},
{"n":5,"zh":"我最近越来越胖了。","vi":"Dạo này mình ngày càng béo ra.","topic":"Thời tiết và sức khỏe","words":[["草","cǎo","thảo","cỏ"],["春","chūn","xuân","mùa xuân"],["当然","dāngrán","đương nhiên","tất nhiên, dĩ nhiên"],["发烧","fā shāo","phát thiêu","sốt, bị sốt"],["感冒","gǎnmào","cảm mạo","bị cảm; cảm cúm"],["季节","jìjié","quý tiết","mùa"],["裙子","qúnzi","quần tử","váy"],["为","wèi","vị","vì; cho"],["夏","xià","hạ","mùa hè"],["用","yòng","dụng","cần (thường dùng 不用: không cần); dùng"],["越","yuè","việt","càng"],["照顾","zhàogù","chiếu cố","chăm sóc"],["最近","zuìjìn","tối cận","gần đây, dạo này"]],"grammar":[{"t":"Trợ từ 了 chỉ sự thay đổi","f":"A / V (O) + 了 (cuối câu)","e":"了 ở cuối câu báo hiệu tình hình đã khác trước: “… rồi”, “… ra”, “không … nữa”. Đây là 了 thay đổi, khác với 了 sau động từ chỉ hành động đã hoàn thành. Phủ định 不…了 nghĩa là “không… nữa”.","ex":[["春天 到 了， 草 也 绿 了。","Mùa xuân đến rồi, cỏ cũng xanh rồi."],["我 不 发烧 了。","Mình hết sốt rồi."],["天气 热 了， 我 可以 穿 裙子 了。","Trời nóng rồi, mình mặc váy được rồi."]]},{"t":"Ngày càng: 越来越 + A/V tâm lý","f":"越来越 + tính từ / động từ tâm lý (+ 了)","e":"Diễn tả mức độ tăng dần theo thời gian: “ngày càng…”. Sau 越来越 KHÔNG thêm 很, 非常, 太. Thường đi với 了 cuối câu. Chỉ dùng với tính từ hoặc động từ tâm lý như 喜欢, 想.","ex":[["天气 越来越 热 了。","Trời ngày càng nóng."],["我 越来越 喜欢 夏天 了。","Mình ngày càng thích mùa hè."],["他 的 汉语 越来越 好。","Tiếng Trung của anh ấy ngày càng giỏi."]]},{"t":"不用 + V (không cần)","f":"不用 + V","e":"不用 nghĩa là “không cần, khỏi phải”, là phủ định của 要 / 得 (phải). Không dùng 不要 trong trường hợp này, vì 不要 nghĩa là “đừng”, nghe như cấm đoán.","ex":[["你 不用 来 接 我， 我 自己 回去。","Bạn không cần đến đón mình, mình tự về."],["明天 是 周末， 不用 上班。","Mai là cuối tuần, không phải đi làm."],["只是 感冒， 不用 去 医院。","Chỉ là cảm thôi, không cần đi viện."]]}],"dialog":[["A","你最近怎么越来越瘦了？","Dạo này sao cậu ngày càng gầy thế?"],["B","我感冒了，还发烧了好几天。","Mình bị cảm, còn sốt mấy ngày liền."],["A","现在好点儿了吗？","Giờ đỡ chút nào chưa?"],["B","好多了，不发烧了。这几天妈妈一直在照顾我。","Đỡ nhiều rồi, hết sốt rồi. Mấy hôm nay mẹ chăm sóc mình suốt."],["A","春天天气变化大，你要多穿点儿衣服。","Mùa xuân thời tiết thay đổi nhiều, cậu phải mặc thêm áo nhé."],["B","当然，谢谢你为我担心。","Tất nhiên rồi, cảm ơn cậu đã lo cho mình."]],"radicals":["夂","火"],"write":["春","夏"],"hz":{"note":"会意字 (chữ hội ý): 明 休 从 看","old":["听说","有点儿","草地"],"prov":["药到病除","Thuốc đến bệnh khỏi"]}},
{"n":6,"zh":"怎么突然找不到了？","vi":"Sao tự nhiên lại không tìm thấy nữa?","topic":"Tìm đồ bị mất","words":[["帮忙","bāng máng","bang mang","giúp, giúp đỡ"],["锻炼","duànliàn","đoán luyện","rèn luyện, tập thể dục"],["刚才","gāngcái","cương tài","lúc nãy, vừa nãy"],["更","gèng","cánh","càng, hơn nữa"],["公园","gōngyuán","công viên","công viên"],["讲","jiǎng","giảng","giảng, nói, kể"],["离开","lí kāi","ly khai","rời khỏi, rời đi"],["聊天","liáotiān","liêu thiên","tán gẫu, nói chuyện phiếm"],["明白","míngbai","minh bạch","hiểu; rõ ràng"],["清楚","qīngchu","thanh sở","rõ, rõ ràng"],["特别","tèbié","đặc biệt","đặc biệt, vô cùng"],["突然","tūrán","đột nhiên","bỗng nhiên, đột nhiên"],["音乐","yīnyuè","âm nhạc","âm nhạc"],["睡着","shuì zháo","thụy trước","ngủ được, ngủ thiếp đi","*"],["眼镜","yǎnjìng","nhãn kính","kính đeo mắt","*"]],"grammar":[{"t":"Bổ ngữ khả năng","f":"V + 得 / 不 + bổ ngữ","e":"V + 得 + bổ ngữ = có thể làm được; V + 不 + bổ ngữ = không thể làm được (do điều kiện khách quan). Người Việt hay nói 不能看清楚 — sai, phải nói 看不清楚.","ex":[["没有 眼镜， 我 看 不 清楚。","Không có kính, tôi nhìn không rõ."],["老师 讲 的， 你 听 得 明白 吗？","Những gì thầy giảng, em nghe có hiểu không?"],["晚上 喝 了 咖啡， 我 睡 不 着。","Buổi tối uống cà phê nên tôi không ngủ được."]]},{"t":"Hỏi vị trí: danh từ + 呢","f":"N + 呢？","e":"Khi không có câu hỏi phía trước, “N + 呢？” nghĩa là “N đâu rồi?”, giống 在哪儿. Câu rất ngắn, hay dùng khi đang tìm người hoặc đồ vật.","ex":[["我 的 眼镜 呢？","Kính của tôi đâu rồi?"],["妈妈 呢？ —— 她 去 公园 锻炼 了。","Mẹ đâu rồi? — Mẹ ra công viên tập thể dục rồi."]]},{"t":"Phân biệt 刚 và 刚才","f":"S + 刚 + V / 刚才 + S + V","e":"刚 là phó từ “vừa mới”, đứng sau chủ ngữ, trước động từ, không đi với 没/不. 刚才 là danh từ thời gian “lúc nãy”, đứng trước hoặc sau chủ ngữ và dùng được với 没/不.","ex":[["他 刚 离开， 你 打 电话 给 他 吧。","Anh ấy vừa mới đi, bạn gọi điện cho anh ấy đi."],["刚才 你 为什么 没 说？","Lúc nãy sao bạn không nói?"],["我 刚 到 家， 他 就 来 了。","Tôi vừa về đến nhà thì anh ấy đến."]]}],"dialog":[["A","我的眼镜呢？刚才还在桌子上，怎么突然找不到了？","Kính của ông đâu rồi? Lúc nãy còn ở trên bàn, sao tự nhiên lại không tìm thấy?"],["B","您别着急，我帮您找找。","Ông đừng sốt ruột, cháu tìm giúp ông."],["A","没有眼镜，我什么都看不清楚。","Không có kính, ông nhìn gì cũng không rõ."],["B","找到了！在您的报纸下面。","Thấy rồi! Ở dưới tờ báo của ông."],["A","太好了！谢谢你帮忙。","Tốt quá! Cảm ơn cháu đã giúp."],["B","不客气，爷爷。","Không có gì ạ, ông."]],"radicals":["方","白"],"write":["刚","讲"],"hz":{"old":["校园","饭桌","花园"],"prov":["万事开头难","Vạn sự khởi đầu nan"]}},
{"n":7,"zh":"我跟她都认识五年了。","vi":"Tôi với cô ấy quen nhau được năm năm rồi","topic":"Thời gian và giờ giấc","words":[["半","bàn","bán","một nửa; rưỡi"],["差","chà","sai","kém, thiếu"],["迟到","chídào","trì đáo","đến muộn"],["感兴趣","gǎn xìngqù","cảm hứng thú","có hứng thú, thích"],["欢迎","huānyíng","hoan nghênh","hoan nghênh, chào mừng"],["接","jiē","tiếp","đón; nhận (điện thoại)"],["结婚","jié hūn","kết hôn","kết hôn, cưới"],["久","jiǔ","cửu","lâu"],["刻","kè","khắc","mười lăm phút"],["同事","tóngshì","đồng sự","đồng nghiệp"],["以前","yǐqián","dĩ tiền","trước đây, trước kia"],["银行","yínháng","ngân hàng","ngân hàng"]],"grammar":[{"t":"Diễn tả khoảng thời gian","f":"V + (了) + thời lượng (+ 了) / V + O + V + thời lượng","e":"Thời lượng (bao lâu) đặt SAU động từ, không đặt trước như “hai năm học”. Có tân ngữ thì lặp lại động từ. Thêm 了 cuối câu nghĩa là việc đó đến giờ vẫn còn tiếp diễn.","ex":[["我 跟 她 认识 五 年 了。","Tôi với cô ấy quen nhau được năm năm rồi."],["我 等 了 他 半 个 小时。","Tôi đã đợi anh ấy nửa tiếng."],["他 学 汉语 学 了 两 年 了。","Anh ấy học tiếng Trung được hai năm rồi."]]},{"t":"Diễn tả sự hứng thú","f":"S + 对 + N + (很 / 不) 感兴趣","e":"Điều mình thích được đưa lên trước bằng 对: 对音乐感兴趣. Người Việt hay nói theo thứ tự “có hứng thú với âm nhạc” thành 感兴趣音乐 — sai.","ex":[["我 对 中国 历史 很 感 兴趣。","Tôi rất có hứng thú với lịch sử Trung Quốc."],["以前 她 对 音乐 不 感 兴趣。","Trước đây cô ấy không hứng thú với âm nhạc."]]},{"t":"Nói giờ với 半, 刻, 差","f":"…点半 / …点一刻 / 差 + số phút + …点","e":"半 = rưỡi, 一刻 = 15 phút, 三刻 = 45 phút. 差 + số phút + giờ = giờ kém: 差五分十点 là mười giờ kém năm. Giờ đồng hồ dùng 分, không dùng 分钟.","ex":[["我们 七 点 半 见。","Bảy giờ rưỡi chúng ta gặp nhau."],["现在 九 点 一 刻。","Bây giờ là chín giờ mười lăm."],["她 的 飞机 差 十 分 十 点 到。","Máy bay của cô ấy đến lúc mười giờ kém mười."]]}],"dialog":[["A","你认识王方多久了？","Chị quen Vương Phương bao lâu rồi?"],["B","我跟她都认识五年了。我们以前是同事。","Tôi với cô ấy quen nhau được năm năm rồi. Trước đây chúng tôi là đồng nghiệp."],["A","你们以前在哪儿工作？","Trước đây các chị làm ở đâu?"],["B","在一家银行。她结婚以后，就离开了银行。","Ở một ngân hàng. Sau khi kết hôn, cô ấy nghỉ việc ở ngân hàng."],["A","她丈夫你也认识吗？","Chồng cô ấy chị cũng quen à?"],["B","认识，他们结婚的时候我也去了。","Quen chứ, lúc họ cưới tôi cũng đến dự."]],"radicals":["工","厂"],"write":["久","刻"],"hz":{"old":["以后","到时候","迎接"],"prov":["一步走错步步错","Sai một bước, bước nào cũng sai"]}},
{"n":8,"zh":"你去哪儿我就去哪儿。","vi":"Em đi đâu thì anh đi đó","topic":"Đi chơi và gặp gỡ","words":[["安静","ānjìng","an tĩnh","yên tĩnh"],["变化","biànhuà","biến hóa","thay đổi, biến đổi"],["层","céng","tằng","tầng (nhà)"],["电梯","diàntī","điện thê","thang máy"],["害怕","hàipà","hại phạ","sợ"],["几乎","jīhū","cơ hồ","hầu như, gần như"],["见面","jiàn miàn","kiến diện","gặp mặt, gặp nhau"],["健康","jiànkāng","kiện khang","khỏe mạnh"],["老","lǎo","lão","già; cũ"],["马上","mǎshàng","mã thượng","ngay, lập tức"],["满意","mǎnyì","mãn ý","hài lòng, vừa ý"],["洗手间","xǐshǒujiān","tẩy thủ gian","nhà vệ sinh"],["熊猫","xióngmāo","hùng miêu","gấu trúc"],["一会儿","yíhuìr","nhất hội nhi","một lát, một chốc"],["重要","zhòngyào","trọng yếu","quan trọng"],["可乐","kělè","khả lạc","nước cô-ca","*"]],"grammar":[{"t":"Phó từ 又: lại (việc đã xảy ra)","f":"S + 又 + V + 了","e":"又 diễn tả hành động lặp lại ĐÃ xảy ra, thường có 了 đi kèm. Cả 又 và 再 đều dịch là “lại”, nên người Việt hay dùng nhầm.","ex":[["他 昨天 迟到 了， 今天 又 迟到 了。","Hôm qua anh ấy đến muộn, hôm nay lại đến muộn."],["你 又 喝 可乐 了？","Con lại uống cô-ca rồi à?"]]},{"t":"Phó từ 再: lại, nữa (việc chưa xảy ra)","f":"S + 再 + V","e":"再 diễn tả hành động sẽ lặp lại trong tương lai, hay dùng khi mời, đề nghị, hẹn. Việc đã xảy ra rồi thì không dùng 再.","ex":[["这 个 电影 很 好看， 我 想 再 看 一 次。","Phim này rất hay, tôi muốn xem thêm lần nữa."],["请 你 再 说 一 次。","Mời bạn nói lại một lần nữa."]]},{"t":"Đại từ nghi vấn dùng linh hoạt","f":"…哪儿…，…就…哪儿 / …什么…就…什么","e":"Một đại từ nghi vấn (哪儿, 什么, 谁…) xuất hiện hai lần, không dùng để hỏi mà chỉ “bất cứ… nào”: vế sau phụ thuộc vế trước, thường có 就. Vế sau phải lặp lại đúng đại từ đó.","ex":[["你 去 哪儿， 我 就 去 哪儿。","Em đi đâu thì anh đi đó."],["你 想 吃 什么 就 吃 什么。","Con muốn ăn gì thì ăn nấy."],["谁 先 到， 谁 就 买 票。","Ai đến trước thì người đó mua vé."]]}],"dialog":[["A","这个周末你想去哪儿玩儿？","Cuối tuần này em muốn đi chơi đâu?"],["B","你去哪儿，我就去哪儿。","Anh đi đâu thì em đi đó."],["A","那我们去看熊猫吧！上次没看到，这次想再去一次。","Vậy mình đi xem gấu trúc nhé! Lần trước không xem được, lần này anh muốn đi lại."],["B","好啊！我们几点见面？","Được đó! Mình gặp nhau lúc mấy giờ?"],["A","九点在门口见，你可别又迟到了！","Chín giờ gặp ở cổng, em đừng có lại đến muộn nhé!"],["B","放心吧，这次我一定早点儿到。","Yên tâm đi, lần này em nhất định đến sớm."]],"radicals":["青","马"],"write":["层","乎"],"hz":{"old":["面试","自学","离婚"],"prov":["站得高，看得远","Đứng càng cao, nhìn càng xa"]}},
{"n":9,"zh":"她的汉语说得跟中国人一样好。","vi":"Cô ấy nói tiếng Trung giỏi như người Trung Quốc","topic":"So sánh và học tập","words":[["班","bān","ban","lớp"],["比较","bǐjiào","tỉ giảo","tương đối, khá; so sánh"],["参加","cānjiā","tham gia","tham gia, tham dự"],["担心","dān xīn","đam tâm","lo lắng"],["放心","fàng xīn","phóng tâm","yên tâm"],["了解","liǎojiě","liễu giải","hiểu rõ, tìm hiểu"],["先","xiān","tiên","trước, trước hết"],["一定","yídìng","nhất định","nhất định, chắc chắn"],["一样","yíyàng","nhất dạng","giống nhau, như nhau"],["影响","yǐngxiǎng","ảnh hưởng","ảnh hưởng"],["中间","zhōngjiān","trung gian","ở giữa"],["最后","zuìhòu","tối hậu","cuối cùng"],["大山","Dàshān","Đại Sơn","Đại Sơn (tên người)"]],"grammar":[{"t":"Cấu trúc 越 A 越 B","f":"S + 越 + V/A + 越 + A","e":"“Càng A càng B”: B thay đổi theo A. A thường là động từ (越说越快, 越学越喜欢). Trước B không thêm 很, 非常.","ex":[["雨 越 下 越 大 了。","Mưa càng lúc càng to."],["他 越 学 越 喜欢 汉语。","Anh ấy càng học càng thích tiếng Trung."]]},{"t":"Cấu trúc 越来越 + tính từ","f":"S + 越来越 + A + 了","e":"越来越 = “ngày càng”, chỉ sự thay đổi theo thời gian, cuối câu thường có 了. Cũng không thêm 很 trước tính từ.","ex":[["天气 越来越 冷 了。","Thời tiết ngày càng lạnh."],["她 的 汉语 越来越 好 了。","Tiếng Trung của cô ấy ngày càng giỏi."]]},{"t":"So sánh ngang bằng: A 跟 B 一样","f":"A + 跟 + B + 一样 (+ tính từ)","e":"A giống B, hoặc A … như B. Tính từ đứng SAU 一样: 一样高 = cao bằng nhau. Phủ định: A 跟 B 不一样. Không thêm 很 trước tính từ.","ex":[["她 的 汉语 说 得 跟 中国人 一样 好。","Cô ấy nói tiếng Trung giỏi như người Trung Quốc."],["我 跟 我 哥哥 一样 高。","Tôi cao bằng anh trai tôi."],["我 的 爱好 跟 你 的 不 一样。","Sở thích của tôi không giống của bạn."]]}],"dialog":[["A","大山的汉语说得怎么样？","Đại Sơn nói tiếng Trung thế nào?"],["B","他的汉语说得跟中国人一样好。","Anh ấy nói tiếng Trung giỏi như người Trung Quốc."],["A","他学了多长时间？","Anh ấy học bao lâu rồi?"],["B","三年。他越学越喜欢汉语。","Ba năm. Anh ấy càng học càng thích tiếng Trung."],["A","听说他还参加了汉语比赛？","Nghe nói anh ấy còn tham gia cuộc thi tiếng Trung?"],["B","对，最后他是第一！","Đúng vậy, cuối cùng anh ấy đứng thứ nhất!"]],"radicals":["耳","厶"],"write":["加","参"],"hz":{"note":"形声字1 (chữ hình thanh 1): 妈 住 放 邻","old":["课间","山路","参赛"],"prov":["三人行，必有我师","Ba người cùng đi ắt có người là thầy ta"]}},
{"n":10,"zh":"数学比历史难多了。","vi":"Môn Toán khó hơn môn Lịch sử nhiều","topic":"So sánh và tìm nhà","words":[["矮","ǎi","ải","thấp, lùn"],["地方","dìfang","địa phương","chỗ, nơi"],["方便","fāngbiàn","phương tiện","thuận tiện, tiện"],["附近","fùjìn","phụ cận","gần đây, xung quanh"],["个子","gèzi","cá tử","vóc người, chiều cao"],["环境","huánjìng","hoàn cảnh","môi trường, khung cảnh"],["换","huàn","hoán","đổi, thay"],["旧","jiù","cựu","cũ"],["历史","lìshǐ","lịch sử","lịch sử; môn Lịch sử"],["骑","qí","kỵ","cưỡi, đi (xe đạp, xe máy)"],["数学","shùxué","số học","môn Toán"],["体育","tǐyù","thể dục","thể dục thể thao; môn Thể dục"],["主要","zhǔyào","chủ yếu","chủ yếu, chính"],["自行车","zìxíngchē","tự hành xa","xe đạp"],["中介","zhōngjiè","trung giới","môi giới, công ty môi giới","*"]],"grammar":[{"t":"So sánh hơn một chút: A 比 B + tính từ + 一点儿 / 一些","f":"A + 比 + B + A + 一点儿 / 一些","e":"Nói A hơn B một chút. Mức độ đặt SAU tính từ. Trong câu có 比 không dùng 很, 非常, 太 trước tính từ.","ex":[["这 件 衣服 比 那 件 贵 一点儿。","Chiếc áo này đắt hơn chiếc kia một chút."],["我 弟弟 比 我 矮 一些。","Em trai tôi thấp hơn tôi một chút."]]},{"t":"So sánh hơn nhiều: A 比 B + tính từ + 得多 / 多了","f":"A + 比 + B + A + 得多 / 多了","e":"Nói A hơn B nhiều. 得多 và 多了 đứng sau tính từ, không đứng trước như “nhiều khó hơn”.","ex":[["数学 比 历史 难 多 了。","Môn Toán khó hơn môn Lịch sử nhiều."],["骑 自行车 比 走路 快 得 多。","Đi xe đạp nhanh hơn đi bộ nhiều."]]},{"t":"Diễn tả số ước lượng","f":"Hai số liền nhau / số + 多 + lượng từ / số + lượng từ + 左右","e":"Hai số liền nhau: 两三个, 五六分钟 (hai ba, năm sáu). Số chục + 多 + lượng từ: 二十多个 (hơn hai mươi). Thêm 左右 sau cụm số: 十分钟左右 (khoảng mười phút).","ex":[["中介 带 我 看 了 三四 个 房子。","Người môi giới dẫn tôi xem ba bốn căn nhà."],["我们 班 有 二十 多 个 学生。","Lớp chúng tôi có hơn hai mươi học sinh."],["走路 去 公园 要 十 分钟 左右。","Đi bộ ra công viên mất khoảng mười phút."]]}],"dialog":[["A","你为什么想换房子？","Sao bạn muốn đổi nhà?"],["B","我住的地方太旧了，环境也不太好。","Chỗ mình ở cũ quá, môi trường cũng không tốt lắm."],["A","你可以找中介帮你看看。","Bạn có thể nhờ môi giới tìm giúp."],["B","我找了，中介说附近有个新房子，比现在的贵一点儿。","Mình nhờ rồi, môi giới nói gần đây có một căn mới, đắt hơn chỗ hiện tại một chút."],["A","那里方便吗？","Chỗ đó có tiện không?"],["B","很方便，骑自行车去公司只要十多分钟。","Tiện lắm, đạp xe đến công ty chỉ hơn mười phút."]],"radicals":["矢","弓"],"write":["旧","换"],"hz":{"old":["换季","地面","主菜"],"prov":["不可同日而语","Không thể so sánh với nhau"]}},
{"n":11,"zh":"别忘了把空调关了。","vi":"Đừng quên tắt điều hòa nhé","topic":"Nhắc việc trước khi ra ngoài","words":[["笔记本","bǐjìběn","bút ký bản","sổ ghi chép; máy tính xách tay"],["词典","cídiǎn","từ điển","từ điển"],["灯","dēng","đăng","đèn"],["地铁","dìtiě","địa thiết","tàu điện ngầm"],["电子邮件","diànzǐ yóujiàn","điện tử bưu kiện","email, thư điện tử"],["关","guān","quan","tắt; đóng"],["还","huán","hoàn","trả (lại)"],["会议","huìyì","hội nghị","cuộc họp, hội nghị"],["结束","jiéshù","kết thúc","kết thúc"],["借","jiè","tá","mượn; cho mượn"],["空调","kōngtiáo","không điều","máy điều hòa"],["口","kǒu","khẩu","miệng; ngụm, miếng (lượng từ)"],["筷子","kuàizi","khoái tử","đũa"],["啤酒","píjiǔ","ti tửu","bia"],["瓶子","píngzi","bình tử","chai, lọ, bình"],["双","shuāng","song","đôi (lượng từ)"],["图书馆","túshūguǎn","đồ thư quán","thư viện"],["忘记","wàngjì","vong ký","quên"],["习惯","xíguàn","tập quán","quen; thói quen"]],"grammar":[{"t":"Câu chữ 把 (1): xử lý một đối tượng","f":"A + 把 + B + V + 了 / thành phần khác","e":"Dùng khi muốn nói A tác động lên vật B cụ thể, đã xác định (tắt cái điều hòa này, trả cuốn từ điển đó). B được đưa lên trước động từ, sau động từ bắt buộc phải có thêm 了 hoặc thành phần khác, không để động từ trơn. Phủ định đặt 没/别 trước 把, không đặt trước động từ.","ex":[["我 已经 把 空调 关 了。","Tôi đã tắt điều hòa rồi."],["你 别 忘 了 把 词典 还 了。","Bạn đừng quên trả từ điển nhé."],["他 没 把 电子邮件 发 给 我。","Anh ấy không gửi email cho tôi."]]},{"t":"Số ước lượng (2): 左右","f":"Số + lượng từ (+ danh từ) + 左右","e":"左右 nghĩa là “khoảng, chừng”, đứng SAU con số. Người Việt nói “khoảng hai mươi phút” nên hay đặt nhầm 左右 lên trước số. Không dùng 左右 cùng lúc với 多 kiểu “二十多分钟左右”.","ex":[["会议 四 点 左右 结束。","Cuộc họp kết thúc vào khoảng bốn giờ."],["坐 地铁 去 要 二十 分钟 左右。","Đi tàu điện ngầm mất khoảng hai mươi phút."],["他 三十 岁 左右。","Anh ấy khoảng ba mươi tuổi."]]},{"t":"Lượng từ 双, 口, 瓶","f":"Số + 双 / 口 / 瓶 + danh từ","e":"双 dùng cho vật đi theo đôi (đũa, giày); 瓶 cho thứ đựng trong chai (bia, nước); 口 chỉ “một ngụm, một miếng”, hay đi với 吃/喝. Giữa số và danh từ luôn phải có lượng từ, không nói 两筷子.","ex":[["请 再 给 我 一 双 筷子。","Cho tôi thêm một đôi đũa nữa."],["我们 要 两 瓶 啤酒。","Chúng tôi lấy hai chai bia."],["你 喝 一 口 吧， 很 好喝。","Bạn uống một ngụm đi, ngon lắm."]]}],"dialog":[["A","你要出去吗？别忘了把空调关了。","Bạn ra ngoài à? Đừng quên tắt điều hòa nhé."],["B","我已经把空调和灯都关了。","Mình tắt cả điều hòa lẫn đèn rồi."],["A","你去哪儿？","Bạn đi đâu thế?"],["B","去图书馆还词典，一个小时左右就回来。","Mình đi thư viện trả từ điển, khoảng một tiếng là về."],["A","你坐地铁去吗？","Bạn đi tàu điện ngầm à?"],["B","对，坐地铁十分钟左右就到了。","Ừ, đi tàu điện ngầm chừng mười phút là tới."]],"radicals":["瓦","酉"],"write":["灯","双"],"hz":{"old":["字典","运动会","开会"],"prov":["贵人多忘事","Người sang hay quên"]}},
{"n":12,"zh":"把重要的东西放在我这儿吧。","vi":"Để đồ quan trọng ở chỗ mình nhé","topic":"Đồ đạc và chuyến đi","words":[["包","bāo","bao","túi, cặp"],["发现","fāxiàn","phát hiện","phát hiện, nhận ra"],["黑板","hēibǎn","hắc bản","bảng đen"],["护照","hùzhào","hộ chiếu","hộ chiếu"],["画","huà","họa","vẽ; bức tranh"],["教","jiāo","giáo","dạy"],["起飞","qǐfēi","khởi phi","cất cánh"],["生气","shēng qì","sinh khí","tức giận, giận"],["司机","sījī","ti cơ","tài xế"],["太阳","tàiyáng","thái dương","mặt trời"],["西","xī","tây","phía tây"],["行李箱","xínglixiāng","hành lý tương","vali"],["需要","xūyào","nhu yếu","cần"],["自己","zìjǐ","tự kỷ","tự mình, bản thân"]],"grammar":[{"t":"So sánh 才 và 就","f":"Thời gian + 就 + V + 了 / Thời gian + 才 + V","e":"就 cho thấy người nói thấy việc xảy ra SỚM, nhanh, dễ (“đã… rồi”); 才 cho thấy việc xảy ra MUỘN, chậm, khó (“mãi… mới”). Câu có 就 thường có 了 ở cuối, câu có 才 thì KHÔNG dùng 了.","ex":[["他 七 点 就 来 了。","Mới bảy giờ anh ấy đã đến rồi."],["他 十 点 才 来。","Mãi mười giờ anh ấy mới đến."],["飞机 晚上 十一 点 才 起飞。","Mãi mười một giờ đêm máy bay mới cất cánh."]]},{"t":"Câu chữ 把 (2): đặt, đưa, trao vật đi đâu","f":"A + 把 + B + V + 在 / 到 / 给 + nơi chốn / người","e":"Khi nói “để cái gì ở đâu”, “mang cái gì đến đâu”, “đưa cái gì cho ai”, tiếng Trung phải dùng 把. Người Việt hay nói theo thứ tự tiếng Việt kiểu 我放护照在包里 — sai; phải nói 我把护照放在包里.","ex":[["我 把 护照 放 在 包 里 了。","Tôi để hộ chiếu trong túi rồi."],["请 你 把 行李箱 拿 到 车 上。","Bạn mang vali lên xe giúp mình."],["我 已经 把 画 送 给 老师 了。","Tôi đã tặng bức tranh cho cô giáo rồi."]]},{"t":"Đại từ 自己","f":"S + 自己 + V / 自己的 + N","e":"自己 là “tự mình, chính mình”. Khi nói “tự làm”, 自己 đứng ngay sau chủ ngữ và trước động từ, không đặt cuối câu như tiếng Việt “tôi làm một mình”.","ex":[["这 张 画 是 我 自己 画 的。","Bức tranh này là tôi tự vẽ."],["行李箱 不 重， 我 自己 拿。","Vali không nặng, tôi tự xách."],["你 要 照顾 好 自己。","Bạn phải tự chăm sóc tốt bản thân nhé."]]}],"dialog":[["A","飞机几点起飞？我们得快点儿吧？","Máy bay mấy giờ cất cánh? Mình phải nhanh lên chứ?"],["B","十点才起飞，不用急。","Mãi mười giờ mới cất cánh, không cần vội."],["A","你的护照呢？","Hộ chiếu của bạn đâu?"],["B","我把护照放在包里了。","Mình để hộ chiếu trong túi rồi."],["A","行李箱很重吧？把它给我吧。","Vali nặng lắm phải không? Đưa nó cho mình đi."],["B","不需要，我自己拿。","Không cần đâu, mình tự xách."]],"radicals":["己","覀"],"write":["画","己"],"hz":{"old":["钱包","电子邮箱","箱子"],"prov":["习惯成自然","Quen tay thành tự nhiên"]}},
{"n":13,"zh":"我是走回来的。","vi":"Mình đi bộ về đấy","topic":"Gia đình và sinh hoạt hằng ngày","words":[["过去","guòqù","quá khứ","(đi) qua đó; quá khứ"],["坏","huài","hoại","hỏng, xấu; (sau tính từ) … lắm, … lả"],["经常","jīngcháng","kinh thường","thường xuyên"],["礼物","lǐwù","lễ vật","quà tặng"],["奶奶","nǎinai","nãi nãi","bà nội"],["起来","qǐlai","khởi lai","dậy, lên (hướng lên)"],["校长","xiàozhǎng","hiệu trưởng","hiệu trưởng"],["爷爷","yéye","gia gia","ông nội"],["一般","yìbān","nhất ban","thông thường, thường thì"],["一边","yìbiān","nhất biên","vừa… vừa…"],["应该","yīnggāi","ứng cai","nên, phải"],["遇到","yùdào","ngộ đáo","gặp (tình cờ)"],["愿意","yuànyì","nguyện ý","bằng lòng, sẵn lòng"],["终于","zhōngyú","chung vu","cuối cùng (thì)"],["生活","shēnghuó","sinh hoạt","cuộc sống","*"]],"grammar":[{"t":"Bổ ngữ xu hướng kép","f":"V + 上 / 下 / 进 / 出 / 回 / 过 / 起 + 来 / 去","e":"Ghép hai hướng sau động từ: 走回来 (đi bộ về), 跑上去 (chạy lên), 站起来 (đứng dậy). 来 là hướng về phía người nói, 去 là rời xa người nói. Nếu có danh từ chỉ nơi chốn thì đặt nó GIỮA hai phần: 走进教室来, 跑回家去, không nói 回来家.","ex":[["我 是 走 回来 的。","Tôi đi bộ về đấy."],["爷爷 从 外面 走 进来 了。","Ông nội từ ngoài đi vào."],["小明 跑 回 家 去 了。","Tiểu Minh chạy về nhà rồi."],["请 大家 站 起来。","Mời mọi người đứng dậy."]]},{"t":"Vừa… vừa…: 一边……一边……","f":"S + 一边 + V1 + 一边 + V2","e":"Diễn tả hai hành động diễn ra cùng lúc. Chủ ngữ đứng trước 一边 đầu tiên; sau mỗi 一边 phải là động từ chỉ hành động, không dùng với tính từ (vừa đẹp vừa rẻ thì dùng 又……又……).","ex":[["奶奶 一边 看 电视 一边 吃 水果。","Bà nội vừa xem tivi vừa ăn hoa quả."],["我们 一边 走 一边 聊 天。","Chúng tôi vừa đi vừa trò chuyện."]]},{"t":"Mức độ cao: V/A + 坏了","f":"饿 / 急 / 忙 + 坏了","e":"Đặt 坏了 sau tính từ hoặc động từ chỉ cảm giác để nói mức độ rất cao, thường là cảm giác khó chịu: “đói lả”, “cuống lắm”. Đã có 坏了 thì không thêm 很, 非常 phía trước.","ex":[["我 饿 坏 了， 快 吃 饭 吧！","Tôi đói lả rồi, ăn cơm nhanh thôi!"],["你 这么 晚 才 回来， 奶奶 急 坏 了。","Con về muộn thế, bà cuống lên rồi đấy."]]}],"dialog":[["A","你怎么现在才回来？","Sao giờ con mới về?"],["B","我是走回来的，路上遇到了校长。","Con đi bộ về ạ, trên đường gặp thầy hiệu trưởng."],["A","你们聊什么了？","Hai thầy trò nói chuyện gì thế?"],["B","我们一边走一边聊学校的生活。","Bọn con vừa đi vừa nói chuyện về cuộc sống ở trường."],["A","你一定饿坏了吧？快进来吃饭。","Chắc con đói lả rồi nhỉ? Mau vào ăn cơm."],["B","是啊，饿坏了！","Vâng ạ, đói lắm rồi!"]],"radicals":["父","舟"],"write":["坏","礼"],"hz":{"note":"形声字2 (chữ hình thanh 2): 爸 草 想 努","old":["红酒","班长","遇见"],"prov":["礼轻情意重","Của ít lòng nhiều"]}},
{"n":14,"zh":"你把水果拿过来。","vi":"Con mang hoa quả lại đây nhé","topic":"Việc nhà và tiếp khách","words":[["阿姨","āyí","a di","cô, dì"],["冰箱","bīngxiāng","băng tương","tủ lạnh"],["菜单","càidān","thái đơn","thực đơn"],["打扫","dǎsǎo","đả tảo","quét dọn"],["干净","gānjìng","can tịnh","sạch sẽ"],["故事","gùshi","cố sự","câu chuyện"],["刮风","guā fēng","quát phong","nổi gió, gió thổi"],["简单","jiǎndān","giản đơn","đơn giản"],["节目","jiémù","tiết mục","chương trình (TV), tiết mục"],["盘子","pánzi","bàn tử","cái đĩa"],["然后","ránhòu","nhiên hậu","sau đó"],["声音","shēngyīn","thanh âm","âm thanh, tiếng"],["叔叔","shūshu","thúc thúc","chú"],["洗澡","xǐ zǎo","tẩy táo","tắm"],["香蕉","xiāngjiāo","hương tiêu","chuối"],["像","xiàng","tượng","giống"],["月亮","yuèliang","nguyệt lượng","mặt trăng"]],"grammar":[{"t":"Câu chữ 把 (3): kết quả và hướng","f":"A + 把 + B + V + bổ ngữ kết quả / bổ ngữ xu hướng","e":"Sau động từ trong câu 把 có thể là kết quả (打扫干净, 洗好, 讲完) hoặc hướng (拿过来, 拿出来). Động từ không được đứng trơn: 我把房间打扫 là câu thiếu, phải nói rõ kết quả 打扫干净了.","ex":[["我 把 房间 打扫 干净 了。","Tôi dọn phòng sạch sẽ rồi."],["你 把 香蕉 拿 过来。","Con mang chuối lại đây."],["请 把 菜单 拿 出来。","Làm ơn lấy thực đơn ra."]]},{"t":"Trước… rồi… sau đó…: 先……，再/又……，然后……","f":"S + 先 + V1，再 / 又 + V2，然后 + V3","e":"Kể các việc theo thứ tự. 再 dùng cho việc sắp làm, 又 dùng cho việc đã làm rồi. 先 là phó từ nên đứng TRƯỚC động từ; người Việt hay nói “tắm trước” thành 洗澡先 — sai.","ex":[["我 先 洗澡， 再 吃 饭， 然后 看 节目。","Tôi tắm trước, rồi ăn cơm, sau đó xem chương trình TV."],["他 先 去 了 超市， 又 去 了 银行。","Anh ấy đi siêu thị trước, rồi lại đi ngân hàng."],["你 先 把 盘子 洗 干净， 然后 放 在 桌子 上。","Con rửa sạch đĩa trước, sau đó đặt lên bàn."]]},{"t":"So sánh giống nhau: 像……一样","f":"A + 像 + B (+ 一样) (+ tính từ)","e":"像 là “giống”. Khi muốn nói “giống như B ở điểm gì”, tính từ đặt ở CUỐI: 像他叔叔一样高. Người Việt hay đặt tính từ lên trước như “cao giống chú” — sai.","ex":[["今天 的 月亮 像 一 个 大 盘子。","Mặt trăng hôm nay giống một cái đĩa lớn."],["他 像 他 叔叔 一样 高。","Cậu ấy cao giống chú mình."]]}],"dialog":[["A","叔叔阿姨快到了，你把香蕉从冰箱里拿出来吧。","Chú dì sắp đến rồi, con lấy chuối trong tủ lạnh ra nhé."],["B","好的。盘子洗干净了吗？","Vâng. Đĩa rửa sạch chưa mẹ?"],["A","洗干净了。你先把香蕉放在盘子里，然后打扫一下桌子。","Rửa sạch rồi. Con xếp chuối vào đĩa trước, sau đó lau dọn bàn một chút."],["B","没问题。外面刮风了，要关门吗？","Không vấn đề gì. Bên ngoài nổi gió rồi, có cần đóng cửa không ạ?"],["A","要，你把门关上吧。","Có, con đóng cửa lại đi."]],"radicals":["皿","亠"],"write":["叔","盘"],"hz":{"old":["名单","读音","买单"],"prov":["先到先得","Đến trước được trước"]}},
{"n":15,"zh":"其他都没什么问题。","vi":"Những chỗ khác đều không có vấn đề gì","topic":"Học tập và văn hóa","words":[["除了","chúle","trừ liễu","ngoài… ra"],["发","fā","phát","gửi (đi); phát"],["花","huā","hoa","tiêu, tốn (tiền, thời gian)"],["极","jí","cực","cực kỳ, hết sức"],["街道","jiēdào","nhai đạo","đường phố"],["节日","jiérì","tiết nhật","ngày lễ, ngày hội"],["句子","jùzi","cú tử","câu"],["练习","liànxí","luyện tập","luyện tập; bài tập"],["留学","liú xué","lưu học","du học"],["其他","qítā","kỳ tha","khác, cái khác"],["上网","shàng wǎng","thượng võng","lên mạng"],["世界","shìjiè","thế giới","thế giới"],["水平","shuǐpíng","thủy bình","trình độ"],["提高","tí gāo","đề cao","nâng cao"],["完成","wán chéng","hoàn thành","hoàn thành"],["文化","wénhuà","văn hóa","văn hóa"],["新闻","xīnwén","tân văn","tin tức"],["要求","yāoqiú","yêu cầu","yêu cầu"],["注意","zhù yì","chú ý","chú ý"],["各","gè","các","các, mỗi","*"],["举行","jǔxíng","cử hành","tổ chức (cuộc họp, cuộc thi…)","*"]],"grammar":[{"t":"Ngoài… ra: 除了……以外，都/还/也……","f":"除了 + X + 以外，S + 都 / 还 / 也 + …","e":"Đi với 都: loại X ra, những cái còn lại đều như nhau (“trừ X”). Đi với 还/也: ngoài X còn thêm cái khác (“ngoài X ra còn…”). X được kẹp giữa 除了 và 以外; 以外 có thể lược bỏ.","ex":[["除了 这 个 句子 以外， 其他 都 没 问题。","Trừ câu này ra, những câu khác đều không có vấn đề."],["除了 春节 以外， 我 还 喜欢 中秋节。","Ngoài Tết ra, tôi còn thích Trung thu."],["除了 汉语， 他 也 学 中国 文化。","Ngoài tiếng Trung, anh ấy cũng học văn hóa Trung Quốc."]]},{"t":"Đại từ nghi vấn dùng linh hoạt (2): 什么/谁/哪儿 + 都/也","f":"什么 / 谁 / 哪儿 + 都 / 也 + (不/没) V; 没什么 + N","e":"Từ để hỏi không dùng để hỏi mà chỉ “bất cứ… nào”: 谁都知道 (ai cũng biết), 哪儿也没去 (chẳng đi đâu cả). 没什么问题 nghĩa là “không có vấn đề gì”. Từ để hỏi phải đứng TRƯỚC 都/也, khác tiếng Việt “không ăn gì cả”.","ex":[["这 个 新闻 谁 都 知道。","Tin tức này ai cũng biết."],["周末 我 哪儿 也 没 去。","Cuối tuần tôi chẳng đi đâu cả."],["我 现在 什么 都 不 想 吃。","Bây giờ tôi chẳng muốn ăn gì cả."],["你 的 练习 没 什么 问题。","Bài tập của bạn không có vấn đề gì."]]},{"t":"Diễn tả mức độ: 极了","f":"Tính từ / động từ tâm lý + 极了","e":"Đặt sau tính từ để nói mức độ cao nhất: “cực kỳ, … vô cùng”. Đã có 极了 thì không thêm 很, 非常, 太 phía trước.","ex":[["节日 的 街道 漂亮 极 了。","Đường phố ngày lễ đẹp vô cùng."],["他 的 汉语 水平 高 极 了。","Trình độ tiếng Trung của anh ấy cực kỳ cao."]]}],"dialog":[["A","老师，我把练习完成了，您看看。","Thưa cô, em làm xong bài tập rồi, cô xem giúp em ạ."],["B","除了这个句子以外，其他都没什么问题。","Trừ câu này ra, những câu khác đều không có vấn đề gì."],["A","这个句子怎么了？","Câu này bị sao ạ?"],["B","你注意一下这个词的用法。你的汉字写得好极了。","Em chú ý cách dùng của từ này nhé. Chữ Hán em viết đẹp lắm."],["A","谢谢老师！我的水平什么时候能提高？","Em cảm ơn cô! Bao giờ trình độ của em mới nâng cao được ạ?"],["B","每天练习，很快就能提高。","Ngày nào cũng luyện tập thì sẽ tiến bộ nhanh thôi."]],"radicals":["田","勹"],"write":["各","句"],"hz":{"old":["电影节","春节","文化节"],"prov":["一是一，二是二","Một là một, hai là hai"]}},
{"n":16,"zh":"我现在累得下了班就想睡觉。","vi":"Giờ mình mệt đến mức tan làm là chỉ muốn đi ngủ","topic":"Sức khỏe và ngoại hình","words":[["鼻子","bízi","tị tử","mũi"],["别人","biérén","biệt nhân","người khác"],["城市","chéngshì","thành thị","thành phố"],["公斤","gōngjīn","công cân","ki-lô-gam (kg)"],["关系","guānxì","quan hệ","quan hệ; liên quan"],["检查","jiǎnchá","kiểm tra","kiểm tra; khám (bệnh)"],["可爱","kě'ài","khả ái","đáng yêu, dễ thương"],["帽子","màozi","mạo tử","cái mũ"],["米","mǐ","mễ","mét (m)"],["皮鞋","píxié","bì hài","giày da"],["认为","rènwéi","nhận vi","cho rằng, nghĩ rằng"],["如果","rúguǒ","như quả","nếu"],["刷牙","shuā yá","xoát nha","đánh răng"],["头发","tóufa","đầu phát","tóc"],["长","zhǎng","trưởng","mọc; lớn lên; trông (có ngoại hình)"],["词语","cíyǔ","từ ngữ","từ ngữ","*"]],"grammar":[{"t":"Câu giả thiết 如果……(的话)，就……","f":"如果 + điều kiện (+ 的话)，(S) + 就 + V","e":"如果 = “nếu”; 的话 ở cuối vế đầu có thể thêm hoặc bỏ; vế sau thường có 就 = “thì”. Lưu ý: 就 là phó từ nên đứng SAU chủ ngữ của vế sau (我们就去), không nói 就我们去 như tiếng Việt “thì chúng ta đi”.","ex":[["如果 明天 下雨 的话，我们 就 不 去 爬山 了。","Nếu mai trời mưa thì chúng ta không đi leo núi nữa."],["如果 你 不 舒服，就 去 医院 检查 一下。","Nếu bạn thấy không khỏe thì đi bệnh viện khám thử đi."]]},{"t":"Bổ ngữ trạng thái phức tạp","f":"V/A + 得 + cụm động từ / cụm chủ-vị","e":"Sau 得 có thể là cả một cụm từ hay một câu nhỏ để tả mức độ, kết quả: 忙得没时间吃饭. Tiếng Việt cần “đến mức / đến nỗi”, tiếng Trung chỉ cần 得 — người Việt hay quên 得.","ex":[["他 忙 得 没 时间 吃饭。","Anh ấy bận đến mức không có thời gian ăn cơm."],["孩子 高兴 得 跳 了 起来。","Đứa bé vui đến nỗi nhảy cẫng lên."],["我 饿 得 不 想 说话。","Mình đói đến mức chẳng muốn nói gì."]]},{"t":"Lặp tính từ đơn âm tiết (AA)","f":"A + A (+ 的)","e":"Tính từ một âm tiết lặp lại để miêu tả sinh động, mức độ cao hơn: 长长的头发, 红红的脸. Sau AA thường có 的; không thêm 很, 非常 hay 不 trước AA.","ex":[["她 的 头发 长长 的。","Tóc cô ấy dài thật dài."],["小狗 的 鼻子 小小 的，很 可爱。","Mũi chú chó con nho nhỏ, rất dễ thương."],["你 慢慢 说，别 着急。","Bạn cứ từ từ nói, đừng sốt ruột."]]}],"dialog":[["A","你最近怎么了？每天回家都不说话。","Dạo này anh sao vậy? Ngày nào về nhà cũng chẳng nói gì."],["B","公司最近太忙了，我忙得下了班就想睡觉。","Dạo này công ty bận quá, anh bận đến mức tan làm là chỉ muốn ngủ."],["A","如果你身体不舒服，就去医院检查一下吧。","Nếu anh thấy người không khỏe thì đi bệnh viện khám thử đi."],["B","我认为没什么关系，休息几天就好了。","Anh nghĩ không sao đâu, nghỉ vài hôm là khỏe thôi."],["A","别人的话你可以不听，我的话你得听啊！","Lời người khác anh có thể không nghe, nhưng lời em thì anh phải nghe đấy!"],["B","好好好，明天我就去检查。","Được rồi được rồi, mai anh đi khám ngay."]],"radicals":["尸","自"],"write":["皮","牙"],"hz":{"old":["词语","运动鞋","体检"],"prov":["钱不是万能的","Tiền không phải là vạn năng"]}},
{"n":17,"zh":"谁都有办法看好你的“病”。","vi":"Ai cũng có cách chữa khỏi “bệnh” của bạn","topic":"Sở thích và lựa chọn","words":[["爱好","àihào","ái hiếu","sở thích"],["办法","bànfǎ","biện pháp","cách, biện pháp"],["饱","bǎo","bão","no (bụng)"],["必须","bìxū","tất tu","nhất định phải, bắt buộc"],["冬","dōng","đông","mùa đông"],["根据","gēnjù","căn cứ","căn cứ vào, dựa vào"],["后来","hòulái","hậu lai","sau đó, về sau"],["决定","juédìng","quyết định","quyết định"],["渴","kě","khát","khát (nước)"],["邻居","línjū","lân cư","hàng xóm"],["请假","qǐng jià","thỉnh giả","xin nghỉ (phép)"],["为了","wèile","vị liễu","để, vì (mục đích)"],["选择","xuǎnzé","tuyển trạch","chọn, lựa chọn"],["一共","yígòng","nhất cộng","tổng cộng"],["情况","qíngkuàng","tình huống","tình hình","*"]],"grammar":[{"t":"Lặp động từ hai âm tiết (ABAB)","f":"AB + AB","e":"Động từ hai âm tiết AB lặp thành ABAB để nói “làm thử, làm một chút” cho nhẹ nhàng: 休息休息, 介绍介绍. Chú ý: lặp động từ là ABAB, KHÔNG phải AABB (锻锻炼炼 là sai).","ex":[["周末 我们 去 公园 锻炼锻炼 吧。","Cuối tuần chúng ta ra công viên tập thể dục một chút nhé."],["你 给 大家 介绍介绍 你 的 爱好 吧。","Bạn giới thiệu một chút về sở thích của mình với mọi người đi."]]},{"t":"Đại từ nghi vấn dùng linh hoạt (3): hai vế hô ứng","f":"… 谁/什么/哪儿/怎么 …，(S) 就 … 谁/什么/哪儿/怎么 …","e":"Cùng một đại từ nghi vấn xuất hiện ở cả hai vế và chỉ cùng một người/vật: 你想吃什么就吃什么 = muốn ăn gì thì ăn nấy. Đây là câu khẳng định, không phải câu hỏi, nên không dùng 吗 và dấu hỏi.","ex":[["你 想 吃 什么，就 吃 什么。","Bạn muốn ăn gì thì ăn nấy."],["谁 先 到，谁 就 去 买 票。","Ai đến trước thì người đó đi mua vé."],["哪儿 好玩儿，我们 就 去 哪儿。","Chỗ nào vui thì chúng ta đi chỗ đó."]]},{"t":"Chỉ mục đích với 为了","f":"为了 + mục đích，S + V","e":"为了 = “để, vì (mục đích)”, thường đặt ở đầu câu, vế sau nói việc làm. Người Việt hay đặt “để…” ở cuối câu; nếu muốn để mục đích ra sau thì phải dùng 是为了.","ex":[["为了 身体 健康，爸爸 每天 都 去 跑步。","Để có sức khỏe tốt, ngày nào bố cũng đi chạy bộ."],["为了 学好 汉语，她 决定 去 中国 留学。","Để học giỏi tiếng Trung, cô ấy quyết định sang Trung Quốc du học."]]}],"dialog":[["A","你怎么了？看起来不太高兴。","Cậu sao thế? Trông không vui lắm."],["B","我想找一个新爱好，可是不知道选择学画画还是学唱歌。","Mình muốn tìm một sở thích mới, nhưng không biết nên chọn học vẽ hay học hát."],["A","这很简单，你喜欢什么就学什么。","Đơn giản thôi, cậu thích gì thì học nấy."],["B","可是两个我都喜欢，决定不了。","Nhưng mình thích cả hai, không quyết được."],["A","那就都试试，哪个有意思就选择哪个。","Thế thì thử cả hai đi, cái nào thú vị thì chọn cái đó."],["B","好办法！我先去了解了解。","Cách hay đấy! Mình đi tìm hiểu một chút trước đã."]],"radicals":["羊","彡"],"write":["冬","必"],"hz":{"note":"形声字3 (chữ hình thanh 3): 园 病 问 闻","old":["婚假","怎么办","喜爱"],"prov":["早睡早起身体好","Ngủ sớm dậy sớm sức khỏe tốt"]}},
{"n":18,"zh":"我相信他们会同意的。","vi":"Mình tin là họ sẽ đồng ý","topic":"Thuyết phục và tin tưởng","words":[["不但……而且……","búdàn……érqiě……","bất đãn … nhi thả","không những… mà còn…"],["地","de","địa","(trợ từ nối trạng ngữ với động từ)"],["动物","dòngwù","động vật","động vật, con vật"],["段","duàn","đoạn","đoạn, khoảng (thời gian, đường)"],["关于","guānyú","quan vu","về (chủ đề)"],["国家","guójiā","quốc gia","đất nước, quốc gia"],["机会","jīhuì","cơ hội","cơ hội, dịp"],["奇怪","qíguài","kỳ quái","lạ, kỳ lạ"],["同意","tóngyì","đồng ý","đồng ý"],["万","wàn","vạn","vạn, mười nghìn"],["相信","xiāngxìn","tương tín","tin, tin tưởng"],["向","xiàng","hướng","về phía; với, đối với"],["有名","yǒumíng","hữu danh","nổi tiếng"],["只","zhī","chích","con (lượng từ cho động vật)"],["种","zhǒng","chủng","loại, kiểu"],["嘴","zuǐ","chủy","miệng, mỏ"],["特点","tèdiǎn","đặc điểm","đặc điểm","*"]],"grammar":[{"t":"Câu điều kiện 只要……，就……","f":"只要 + điều kiện，(S) + 就 + V","e":"只要 = “chỉ cần”: nêu một điều kiện đơn giản là đủ để có kết quả ở vế sau; vế sau dùng 就. Đừng nhầm với 只有……才…… (chỉ có… mới…) — 只要 đi với 就, không đi với 才.","ex":[["只要 你 努力，你 的 汉语 就 会 提高。","Chỉ cần bạn cố gắng thì tiếng Trung của bạn sẽ tiến bộ."],["只要 不 下雨，我们 就 去 动物园。","Chỉ cần trời không mưa là chúng ta đi sở thú."]]},{"t":"Giới từ 关于","f":"关于 + chủ đề (+ 的 + N)","e":"关于 = “về (chủ đề gì)”. Cụm 关于… có thể đứng đầu câu, hoặc làm định ngữ có 的 đứng TRƯỚC danh từ: 关于动物的书. Người Việt hay nói theo thứ tự “sách về động vật” thành 书关于动物 — sai.","ex":[["我 想 看 关于 中国 历史 的 书。","Mình muốn đọc sách về lịch sử Trung Quốc."],["关于 这 件 事，我 还 没 决定。","Về chuyện này, mình vẫn chưa quyết định."]]},{"t":"Câu tăng tiến 不但……而且……","f":"S + 不但 + A/V，而且 + A/V","e":"“Không những… mà còn…”. Nếu hai vế cùng một chủ ngữ thì chủ ngữ đứng TRƯỚC 不但; vế sau thường có thêm 也/还.","ex":[["这 只 小狗 不但 很 可爱，而且 很 聪明。","Chú chó nhỏ này không những dễ thương mà còn rất thông minh."],["他 不但 会 说 汉语，而且 还 会 写 很多 汉字。","Anh ấy không những biết nói tiếng Trung mà còn biết viết rất nhiều chữ Hán."]]}],"dialog":[["A","我有一个去中国留学的机会，可是还没告诉爸爸妈妈。","Mình có cơ hội sang Trung Quốc du học, nhưng vẫn chưa nói với bố mẹ."],["B","别担心，只要你好好地跟他们说，他们就会同意的。","Đừng lo, chỉ cần cậu nói chuyện đàng hoàng với họ thì họ sẽ đồng ý thôi."],["A","你真的这样认为吗？","Cậu thật sự nghĩ vậy à?"],["B","我相信他们会同意的。这个机会不但很好，而且很难得。","Mình tin là họ sẽ đồng ý. Cơ hội này không những tốt mà còn rất hiếm có."],["A","你说得对，今天晚上我就向他们介绍一下这个学校。","Cậu nói đúng, tối nay mình sẽ giới thiệu với bố mẹ về ngôi trường này."],["B","好，明天告诉我他们怎么说。","Ừ, mai kể cho mình nghe họ nói gì nhé."]],"radicals":["虫","牛"],"write":["万","向"],"hz":{"old":["动物园","人名","自信"],"prov":["见怪不怪","Thấy lạ mãi thành quen"]}},
{"n":19,"zh":"你没看出来吗？","vi":"Bạn không nhìn ra à?","topic":"Nhận ra và nhớ lại","words":[["船","chuán","thuyền","thuyền, tàu thủy"],["短","duǎn","đoản","ngắn"],["耳朵","ěrduo","nhĩ đóa","tai"],["过","guò","quá","đón, ăn (Tết, sinh nhật); trải qua"],["经过","jīngguò","kinh quá","đi qua, ngang qua"],["哭","kū","khốc","khóc"],["蓝","lán","lam","màu xanh lam, xanh da trời"],["脸","liǎn","kiểm","mặt, khuôn mặt"],["马","mǎ","mã","ngựa"],["鸟","niǎo","điểu","chim"],["秋","qiū","thu","mùa thu"],["位","wèi","vị","vị (lượng từ chỉ người, lịch sự)"],["张","zhāng","trương","tờ, tấm (lượng từ cho vật phẳng)"],["黄河","Huáng Hé","Hoàng Hà","sông Hoàng Hà"]],"grammar":[{"t":"Nghĩa mở rộng của bổ ngữ xu hướng: 出来","f":"V + 出来","e":"出来 ngoài nghĩa “đi ra” còn có nghĩa “nhận ra, làm ra được”: 看出来 (nhìn ra), 听出来 (nghe ra), 想出来 (nghĩ ra). Phủ định dùng 没 + V + 出来, không thêm 了.","ex":[["你 没 看 出来 吗？她 刚才 哭 过。","Bạn không nhìn ra à? Cô ấy vừa khóc xong."],["我 听 出来 了，这 是 妈妈 的 声音。","Mình nghe ra rồi, đây là giọng của mẹ."],["这个 办法 是 谁 想 出来 的？","Cách này là ai nghĩ ra vậy?"]]},{"t":"Nghĩa mở rộng của bổ ngữ xu hướng: 起来, 下去, 下来","f":"V + 起来 / 下去 / 下来","e":"想起来 = nhớ ra; V + 下去 = tiếp tục làm tiếp; V + 下来 = ghi lại, giữ lại (写下来, 记下来). Người Việt hay nhầm “nói tiếp” thành 说下来 — phải là 说下去.","ex":[["我 想 起来 了，他 叫 张东。","Mình nhớ ra rồi, anh ấy tên là Trương Đông."],["你 说 下去，我们 都 在 听。","Bạn nói tiếp đi, bọn mình đều đang nghe."],["老师 说 的 话，我 都 记 下来 了。","Lời thầy nói, mình đều ghi lại hết rồi."]]},{"t":"Câu kiêm ngữ với 使, 叫, 让","f":"S + 使/叫/让 + người + V/A","e":"Nghĩa là “khiến, làm cho, bảo (ai làm gì)”. 叫 và 让 dùng nhiều trong khẩu ngữ, có thể là “bảo/cho phép”; 使 trang trọng hơn, thường đi với từ chỉ cảm xúc, trạng thái: 使人高兴. Không dịch “làm cho” thành 做.","ex":[["这 件 事 使 她 很 难过。","Chuyện này khiến cô ấy rất buồn."],["妈妈 叫 我 早点儿 回家。","Mẹ bảo mình về nhà sớm một chút."],["他 的 话 让 我 很 高兴。","Lời anh ấy làm mình rất vui."]]}],"dialog":[["A","李月今天怎么了？她的眼睛红红的。","Lý Nguyệt hôm nay sao vậy? Mắt cô ấy đỏ hoe."],["B","你没看出来吗？她刚才哭过。","Cậu không nhìn ra à? Cô ấy vừa khóc xong."],["A","为什么哭？谁让她不高兴了？","Sao lại khóc? Ai làm cô ấy buồn vậy?"],["B","她的小猫找不到了。","Con mèo nhỏ của cô ấy bị lạc rồi."],["A","我想起来了，昨天我经过公园的时候，看到了一只白色的小猫！","Mình nhớ ra rồi, hôm qua lúc đi ngang công viên, mình có thấy một con mèo trắng nhỏ!"],["B","真的？快去告诉她，这件事一定会使她高兴起来。","Thật à? Mau đi báo cô ấy đi, chuyện này chắc chắn sẽ làm cô ấy vui lên."]],"radicals":["鸟","戈"],"write":["马","鸟"],"hz":{"old":["前年","路过","运动服"],"prov":["百闻不如一见","Trăm nghe không bằng một thấy"]}},
{"n":20,"zh":"我被他影响了。","vi":"Mình bị cậu ấy ảnh hưởng rồi","topic":"Ảnh hưởng và cố gắng","words":[["被","bèi","bị","bị, được (dùng trong câu bị động)"],["成绩","chéngjì","thành tích","thành tích, kết quả (học tập)"],["东","dōng","đông","phía đông"],["多么","duōme","đa ma","biết bao, thật là (cảm thán)"],["关心","guānxīn","quan tâm","quan tâm"],["解决","jiějué","giải quyết","giải quyết"],["难过","nánguò","nan quá","buồn, khó chịu (trong lòng)"],["试","shì","thí","thử"],["碗","wǎn","oản","cái bát; bát (lượng từ)"],["信用卡","xìnyòngkǎ","tín dụng tạp","thẻ tín dụng"],["照相机","zhàoxiàngjī","chiếu tướng cơ","máy ảnh"],["只有……才……","zhǐyǒu……cái……","chỉ hữu … tài","chỉ có… mới…"],["真正","zhēnzhèng","chân chính","thật sự, đích thực","*"]],"grammar":[{"t":"Câu chữ 被 (câu bị động)","f":"S (người/vật chịu tác động) + 被 + (người làm) + V + thành phần khác","e":"被 dùng khi chủ ngữ là người/vật chịu tác động, thường mang ý không mong muốn. Động từ sau 被 không đứng một mình mà phải có 了, bổ ngữ… (拿走了, 打坏了). Phủ định: 没 đặt TRƯỚC 被.","ex":[["我 的 照相机 被 人 拿走 了。","Máy ảnh của mình bị người ta lấy mất rồi."],["奶奶 的 碗 被 小明 踢 坏 了。","Cái bát của bà bị Tiểu Minh đá vỡ rồi."],["我 的 信用卡 没 被 拿走。","Thẻ tín dụng của mình không bị lấy mất."]]},{"t":"Câu điều kiện 只有……，才……","f":"只有 + điều kiện，(S) + 才 + V","e":"只有 = “chỉ có”: nêu điều kiện duy nhất, bắt buộc phải có; vế sau dùng 才 = “mới”, không dùng 就. So sánh: 只要……就…… (chỉ cần… là…) nhẹ hơn, còn 只有……才…… nhấn mạnh “không có thì không được”.","ex":[["只有 多 练习，才 能 说 好 汉语。","Chỉ có luyện tập nhiều mới nói giỏi tiếng Trung được."],["只有 认真 学习，成绩 才 会 提高。","Chỉ có học hành chăm chỉ thì thành tích mới tiến bộ."]]},{"t":"Câu cảm thán với 多么","f":"多么 + A + 啊！","e":"多么 = “biết bao, thật là…”, dùng trong câu cảm thán, cuối câu thường có 啊. Khẩu ngữ hay nói gọn là 多. 多么 đã chỉ mức độ cao nên không thêm 很, 非常.","ex":[["这里 的 秋天 多么 漂亮 啊！","Mùa thu ở đây đẹp biết bao!"],["多么 可爱 的 孩子 啊！","Đứa bé thật là đáng yêu!"]]}],"dialog":[["A","你的成绩怎么提高得这么快？","Sao thành tích của cậu tiến bộ nhanh thế?"],["B","我被我的同学影响了。","Mình bị bạn cùng lớp ảnh hưởng đấy."],["A","怎么影响的？","Ảnh hưởng thế nào?"],["B","他每天早上六点起床学习，我也跟他一起学。","Ngày nào cậu ấy cũng dậy lúc sáu giờ để học, mình cũng học cùng cậu ấy."],["A","看来只有努力，才能有好成绩。","Xem ra chỉ có cố gắng mới có thành tích tốt."],["B","对！真正的好学生都是这样的。","Đúng vậy! Học sinh giỏi thật sự đều như thế cả."]],"radicals":["气","石"],"write":["成","被"],"hz":{"old":["碗筷","房卡","东北"],"prov":["车到山前必有路","Xe đến trước núi ắt có đường"]}}];
const RADICALS={"土":["土","Thổ","đất","地在坐块"],"十":["十","Thập","mười","十千午南"],"车":["车","Xa","xe","车辆轻较"],"禾":["禾","Hòa","cây lúa","和秋秘种"],"衤":["衤 (衣)","Y","quần áo","衬衫裤裙"],"米":["米","Mễ","gạo","米料粉糕"],"力":["力","Lực","sức lực","力努动办"],"立":["立","Lập","đứng","立站亲"],"夂":["夂","Truy","đi theo sau","夏冬备复"],"火":["火","Hỏa","lửa","火烧灯炒"],"方":["方","Phương","vuông; phương hướng","方放房旅"],"白":["白","Bạch","màu trắng","白百的怕"],"工":["工","Công","công việc, người thợ","工差左"],"厂":["厂","Hán","sườn núi, mái che","厂历厅厕"],"青":["青","Thanh","màu xanh","静请清晴"],"马":["马","Mã","con ngựa","妈吗骑"],"厶":["厶","Khư","riêng tư","参去能会"],"耳":["耳","Nhĩ","cái tai","耳取聪闻"],"矢":["矢","Thỉ","mũi tên","矮知短"],"弓":["弓","Cung","cái cung","弓张弟强"],"瓦":["瓦","Ngõa","ngói; đồ gốm","瓶瓷瓦"],"酉":["酉","Dậu","bình rượu; rượu","酒醒配"],"己":["己","Kỷ","bản thân","己记起"],"覀":["覀","Á","che đậy","西要票"],"父":["父","Phụ","cha","爷爸父"],"舟":["舟","Chu","thuyền","般船舟"],"皿":["皿","Mãnh","bát đĩa, đồ đựng","盘盒盐"],"亠":["亠","Đầu","nắp, phần trên","亮京六交"],"田":["田","Điền","ruộng","界留男画"],"勹":["勹","Bao","bọc, bao lấy","句包勺"],"尸":["尸","Thi","thân người; mái che","刷层局屋"],"自":["自","Tự","tự mình (vốn là hình cái mũi)","自鼻息臭"],"彡":["彡","Sam","lông tóc dài; nét trang trí","须影形彩"],"羊":["羊","Dương","con dê, con cừu","羊美着差"],"牛":["牜","Ngưu","con trâu, con bò","物特牛告"],"虫":["虫","Trùng","sâu bọ, côn trùng","虫蛋虾蚊"],"鸟":["鸟","Điểu","con chim","鸟鸡鸭"],"戈":["戈","Qua","cây giáo","我成或戏"],"石":["石","Thạch","đá","碗石破码"],"气":["气","Khí","hơi, không khí","气汽"]};
