/* HSK3 Bài 4–6 */
const w3b_I=WA_INK;
const w3b_check=(x,y,r,d)=>`<g class="wa-pop" style="transform-origin:${x}px ${y}px;animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#3fb37f" stroke="${w3b_I}" stroke-width="1.6"/><path d="M${x-r*.5},${y} L${x-r*.12},${y+r*.38} L${x+r*.55},${y-r*.38}" fill="none" stroke="#fff" stroke-width="${r*.28}" stroke-linecap="round" stroke-linejoin="round"/></g>`;
const w3b_sun=(x,y,r,cls)=>`<g class="${cls||'wa-pulse'}" style="transform-origin:${x}px ${y}px">${[0,45,90,135,180,225,270,315].map(a=>{const c=Math.cos(a*Math.PI/180),s=Math.sin(a*Math.PI/180);return `<path d="M${(x+c*(r+4)).toFixed(1)},${(y+s*(r+4)).toFixed(1)} L${(x+c*(r+10)).toFixed(1)},${(y+s*(r+10)).toFixed(1)}" stroke="#f4a52a" stroke-width="3" stroke-linecap="round"/>`;}).join('')}<circle cx="${x}" cy="${y}" r="${r}" fill="#ffd23f" stroke="${w3b_I}" stroke-width="1.8"/></g>`;
const w3b_tree=(x,c,h)=>{h=h||46;return `<rect x="${x-4}" y="${112-h*.45}" width="8" height="${h*.45}" rx="2" fill="#9a6a3f" stroke="${w3b_I}" stroke-width="1.5"/><circle cx="${x}" cy="${112-h*.62}" r="${h*.36}" fill="${c||'#5cb85c'}" stroke="${w3b_I}" stroke-width="1.8"/>`;};
const w3b_flower=(x,y,c,d)=>`<g class="wa-swing" style="transform-origin:${x}px ${y+14}px;animation-delay:${d||0}s"><path d="M${x},${y} L${x},${y+14}" stroke="#3f9a4f" stroke-width="2.2"/>${[0,72,144,216,288].map(a=>`<circle cx="${(x+4.5*Math.cos(a*Math.PI/180)).toFixed(1)}" cy="${(y+4.5*Math.sin(a*Math.PI/180)).toFixed(1)}" r="3.6" fill="${c||'#ff8fb1'}" stroke="${w3b_I}" stroke-width="1"/>`).join('')}<circle cx="${x}" cy="${y}" r="2.6" fill="#ffd23f"/></g>`;
const w3b_cake=(x,y,s)=>`<g transform="translate(${x} ${y}) scale(${s||1})"><rect x="-30" y="-6" width="60" height="30" rx="6" fill="#fbe3c0" stroke="${w3b_I}" stroke-width="1.8"/><rect x="-30" y="6" width="60" height="5" fill="#c97a4a"/><rect x="-24" y="-28" width="48" height="24" rx="5" fill="#ffd6e4" stroke="${w3b_I}" stroke-width="1.8"/><path d="M-24,-20 q6,6 12,0 q6,6 12,0 q6,6 12,0 q6,6 12,0" fill="none" stroke="#fff" stroke-width="4"/><path d="M-30,2 q7.5,7 15,0 q7.5,7 15,0 q7.5,7 15,0 q7.5,7 15,0" fill="none" stroke="#fff" stroke-width="4"/><circle cx="0" cy="-34" r="6" fill="#e5383b" stroke="${w3b_I}" stroke-width="1.5"/><path d="M0,-40 l3,-4" stroke="#3f9a4f" stroke-width="2"/></g>`;
const w3b_bulb=(x,y,cls)=>`<g class="${cls||'wa-pulse'}" style="transform-origin:${x}px ${y}px"><circle cx="${x}" cy="${y}" r="20" fill="#fff3a6" opacity=".7"/><path d="M${x-9},${y+2} a11,11 0 1 1 18,0 q-3,3 -3,8 h-12 q0,-5 -3,-8Z" fill="#ffd23f" stroke="${w3b_I}" stroke-width="1.7"/><rect x="${x-5.5}" y="${y+10}" width="11" height="6" rx="2" fill="#aab" stroke="${w3b_I}" stroke-width="1.4"/></g>`;
const w3b_bed=(x,w)=>`<rect x="${x}" y="84" width="${w}" height="20" rx="4" fill="#9a6a3f" stroke="${w3b_I}" stroke-width="1.8"/><rect x="${x}" y="64" width="10" height="46" rx="3" fill="#7a5230" stroke="${w3b_I}" stroke-width="1.6"/><rect x="${x+w-8}" y="76" width="8" height="34" rx="3" fill="#7a5230" stroke="${w3b_I}" stroke-width="1.6"/>`;
const w3b_head=(x,y,o)=>{o=o||{};const sk=o.skin||WA_SKIN;const eyes=o.sleep?`<path d="M${x-7},${y+1} q2.5,2.5 5,0 M${x+2},${y+1} q2.5,2.5 5,0" fill="none" stroke="${w3b_I}" stroke-width="1.7" stroke-linecap="round"/>`:o.sad?`<circle cx="${x-5}" cy="${y+1}" r="1.8" fill="${w3b_I}"/><circle cx="${x+5}" cy="${y+1}" r="1.8" fill="${w3b_I}"/><path d="M${x-4},${y+9} q4,-3.5 8,0" fill="none" stroke="${w3b_I}" stroke-width="1.7" stroke-linecap="round"/>`:`<circle cx="${x-5}" cy="${y+1}" r="1.8" fill="${w3b_I}"/><circle cx="${x+5}" cy="${y+1}" r="1.8" fill="${w3b_I}"/>`;
  return `<circle cx="${x}" cy="${y}" r="14" fill="${sk}" stroke="${w3b_I}" stroke-width="1.8"/><path d="M${x-14},${y-1} Q${x-16},${y-17} ${x},${y-17} Q${x+16},${y-17} ${x+14},${y-1} Q${x+8},${y-10} ${x},${y-9} Q${x-8},${y-10} ${x-14},${y-1}Z" fill="${o.hairC||'#3b2a22'}" stroke="${w3b_I}" stroke-width="1.5"/>${o.red?`<ellipse cx="${x-8}" cy="${y+5}" rx="4" ry="2.6" fill="#ff6b6b" opacity=".85"/><ellipse cx="${x+8}" cy="${y+5}" rx="4" ry="2.6" fill="#ff6b6b" opacity=".85"/>`:`<ellipse cx="${x-9}" cy="${y+5}" rx="2.5" ry="1.6" fill="#ff9e9e" opacity=".75"/><ellipse cx="${x+9}" cy="${y+5}" rx="2.5" ry="1.6" fill="#ff9e9e" opacity=".75"/>`}${eyes}`;};
