const w3d_cross=(x,y,r,d)=>`<g class="wa-pop" style="transform-origin:${x}px ${y}px;animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#e5383b" stroke="${w3d_I}" stroke-width="1.6"/><path d="M${x-r*.4},${y-r*.4} L${x+r*.4},${y+r*.4} M${x+r*.4},${y-r*.4} L${x-r*.4},${y+r*.4}" stroke="#fff" stroke-width="${(r*.26).toFixed(1)}" stroke-linecap="round"/></g>`;
const w3d_book=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="${c}" stroke="${w3d_I}" stroke-width="1.5"/><rect x="${x+w*.2}" y="${y+h*.2}" width="${w*.6}" height="${h*.15}" fill="#fff" opacity=".7"/>`;
const w3d_laptop=(x,y,inner)=>`<rect x="${x}" y="${y}" width="60" height="40" rx="4" fill="#3d4a66" stroke="${w3d_I}" stroke-width="1.8"/><rect x="${x+4}" y="${y+4}" width="52" height="32" rx="2" fill="#cfe6f5"/>${inner||''}<path d="M${x-8},${y+40} L${x+68},${y+40} L${x+62},${y+48} L${x-2},${y+48}Z" fill="#9fb0cc" stroke="${w3d_I}" stroke-width="1.8" stroke-linejoin="round"/>`;
