/* HSK3 Bài 14–16 */
const w3e_I=WA_INK;
const w3e_check=(x,y,r,d)=>`<g class="wa-pop" style="animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#3fb37f" stroke="${w3e_I}" stroke-width="1.6"/><path d="M${x-r*.5},${y} L${x-r*.12},${y+r*.38} L${x+r*.55},${y-r*.38}" fill="none" stroke="#fff" stroke-width="${(r*.28).toFixed(1)}" stroke-linecap="round" stroke-linejoin="round"/></g>`;
const w3e_cross=(x,y,r,d)=>`<g class="wa-pop" style="animation-delay:${d||0}s"><circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#e5383b" stroke-width="${(r*.22).toFixed(1)}"/><path d="M${x-r*.45},${y-r*.45} L${x+r*.45},${y+r*.45} M${x+r*.45},${y-r*.45} L${x-r*.45},${y+r*.45}" stroke="#e5383b" stroke-width="${(r*.22).toFixed(1)}" stroke-linecap="round"/></g>`;
const w3e_rock=(a,b,x,y,dur)=>`<animateTransform attributeName="transform" type="rotate" values="${a} ${x} ${y};${b} ${x} ${y};${a} ${x} ${y}" dur="${dur}s" repeatCount="indefinite"/>`;
const w3e_move=(vals,dur)=>`<animateTransform attributeName="transform" type="translate" values="${vals}" dur="${dur}s" repeatCount="indefinite"/>`;
const w3e_banana=(x,y,a,s)=>`<g transform="translate(${x} ${y}) rotate(${a}) scale(${s||1})"><path d="M0,0 Q18,24 46,12 Q51,9 48,5 Q24,13 5,-5Z" fill="#ffd93b" stroke="${w3e_I}" stroke-width="1.6" stroke-linejoin="round"/><path d="M8,3 Q22,16 42,10" fill="none" stroke="#e8b923" stroke-width="2"/><path d="M48,6 L51,9" stroke="#5a3a22" stroke-width="3" stroke-linecap="round"/></g>`;
const w3e_snow=(x,y,r,d)=>`<g class="wa-tw" style="transform-origin:${x}px ${y}px;animation-delay:${d||0}s" stroke="#7cc4f0" stroke-width="2.2" stroke-linecap="round"><path d="M${x-r},${y} L${x+r},${y} M${x-r*.5},${y-r*.87} L${x+r*.5},${y+r*.87} M${x+r*.5},${y-r*.87} L${x-r*.5},${y+r*.87}"/></g>`;
